body.script:
//
					const cfg   = document.getElementById('cfg').dataset;
					const ASSET = cfg.asset;
					// Server-rendered `?as_of=` from the page's own URL (see
					// time_machine_chart's own docstring) — pre-fills the "As
					// Of" input so a specific historical view is bookmarkable.
					// Interpreted as EUROPE/BERLIN wall-clock time (the picker's
					// own zone — see setAsOfInput()/berlinNaiveToUtcIso()
					// below), same as a value the user types; it is converted
					// to UTC client-side before any backend call. Empty string
					// (not set) means "start at now", same as a bare
					// /tm/<asset> visit.
					const INITIAL_AS_OF = cfg.asOf || '';
					// Coinbase spot, same symbol convention /l24/<asset>
					// uses (server-side _COINBASE_SYMBOL_MAP).
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;

					// "As Of" — the single moment this whole page is frozen at.
					// The <input type="datetime-local"> and the URL's own
					// `?as_of=` are both EUROPE/BERLIN wall-clock time (DST-
					// aware — the picker's label says "As Of (Berlin)"), per
					// product decision, since this Thales tool's users think in
					// Berlin time. AS_OF_ISO, by contrast, is always the
					// equivalent naive-UTC "YYYY-MM-DDTHH:MM:SS" (converted from
					// the Berlin input by berlinNaiveToUtcIso() in
					// setAsOfInput(); seconds forced to :00 so the server's
					// _parse_as_of_param (main.py) always gets a fully-formed
					// ISO string regardless of Python's own fromisoformat
					// version quirks around omitted seconds). Every fetch on
					// this page appends `&as_of=` + AS_OF_ISO (so the backend
					// always receives UTC, matching this addon's UTC-anchored
					// trade-window convention), and the Window vertical line
					// below is measured back from it too (asOfEpochSeconds()),
					// not from real "now".
					let AS_OF_ISO = null;

					function pad(n) { return String(n).padStart(2, '0'); }

					// Formats a JS Date as a naive-UTC "YYYY-MM-DDTHH:MM"
					// string (UTC getters, not local) — used only as the tail
					// end of berlinNaiveToUtcIso() below.
					function toDatetimeLocalUTC(date) {
						return date.getUTCFullYear() + '-' + pad(date.getUTCMonth() + 1) + '-' + pad(date.getUTCDate())
							+ 'T' + pad(date.getUTCHours()) + ':' + pad(date.getUTCMinutes());
					}

					// Formats a JS Date as the Europe/Berlin wall-clock
					// "YYYY-MM-DDTHH:00" string the <input type="datetime-
					// local"> shows — DST-aware via Intl ('sv-SE' renders an
					// ISO-like "YYYY-MM-DD HH:MM:SS"; the space becomes 'T').
					// Minutes are ALWAYS truncated to :00 (per product
					// decision — the picker only ever operates at hour
					// granularity, matching the Window dropdown's own
					// whole-hour steps and the hour-granular trade filtering
					// downstream). Used for the "Now" button and, via
					// defaultAsOfBerlinNaive(), the page's own default.
					function toDatetimeLocalBerlin(date) {
						return date.toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' }).replace(' ', 'T').slice(0, 13) + ':00';
					}

					// Europe/Berlin's UTC offset in seconds (Berlin - UTC,
					// positive) at `refDate`, DST-aware (CET/CEST) via Intl's
					// own timezone data rather than a fixed UTC+1/+2 guess —
					// same "diff two toLocaleString renderings of the same
					// instant" idiom the page-wide `tzOffset` above uses, just
					// for Berlin instead of the viewer's own browser zone.
					function berlinOffsetSeconds(refDate) {
						const utc = new Date(refDate.toLocaleString('en-US', { timeZone: 'UTC' }));
						const berlin = new Date(refDate.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
						return (berlin - utc) / 1000;
					}

					// Converts a Berlin wall-clock "YYYY-MM-DDTHH:MM[:SS]"
					// string (what the picker / URL `?as_of=` carry) to the
					// equivalent naive-UTC "YYYY-MM-DDTHH:MM:SS" string
					// (AS_OF_ISO — what every backend call and asOfEpochSeconds()
					// expect). DST-aware: the offset is resolved for the TARGET
					// date itself (CET vs CEST), not "now", by building a
					// first-guess UTC instant from the wall-clock components and
					// reading Berlin's offset at that instant. The ~1h
					// ambiguity right at a DST transition (a nonexistent
					// spring-forward hour, a doubled fall-back hour) is inherent
					// to any naive-local→instant conversion and immaterial for a
					// historical-inspection tool.
					function berlinNaiveToUtcIso(berlinNaive) {
						const [datePart, timePart] = berlinNaive.slice(0, 16).split('T');
						const [y, m, d] = datePart.split('-').map(Number);
						const [H, M] = timePart.split(':').map(Number);
						const guessUTC = Date.UTC(y, m - 1, d, H, M, 0);
						const offsetSec = berlinOffsetSeconds(new Date(guessUTC));
						return toDatetimeLocalUTC(new Date(guessUTC - offsetSec * 1000)) + ':00';
					}

					// The page's own default "As Of" when no `?as_of=` was
					// given on the URL — the current Europe/Berlin date and
					// hour, minutes truncated to :00 (e.g. 11:37 Berlin →
					// "…T11:00"), per product decision. Just
					// toDatetimeLocalBerlin(now), which already zeroes the
					// minutes and resolves Berlin's own wall clock (DST-aware,
					// and Berlin's own calendar day near midnight) for us.
					function defaultAsOfBerlinNaive() {
						return toDatetimeLocalBerlin(new Date());
					}

					function setAsOfInput(value) {
						// `value` is a Berlin wall-clock string — a typed value,
						// the "Now" button's toDatetimeLocalBerlin(), or a
						// server-rendered URL `?as_of=` (not guaranteed to match
						// the plain "YYYY-MM-DDTHH:MM" shape the <input>'s own
						// .value getter produces, so sliced to 16 chars first).
						const berlin = value.slice(0, 16);
						document.getElementById('as-of-input').value = berlin;
						// AS_OF_ISO is the equivalent naive-UTC instant — this is
						// the single Berlin→UTC conversion point on the page.
						AS_OF_ISO = berlinNaiveToUtcIso(berlin);
					}

					// AS_OF_ISO is a naive-UTC string (berlinNaiveToUtcIso()'s
					// output), so a bare `new Date(AS_OF_ISO)` would parse it as
					// browser-LOCAL time in most engines — appending 'Z' forces
					// UTC parsing instead. Returns null if AS_OF_ISO isn't set
					// yet (before setAsOfInput()'s first call), so callers can
					// treat that as "nothing to position against" rather than
					// NaN.
					function asOfEpochSeconds() {
						if (!AS_OF_ISO) return null;
						return Math.floor(Date.parse(AS_OF_ISO + 'Z') / 1000);
					}

					// "Timeframe" dropdown — same options as /l24/<asset>'s
					// own, defaulting to 1h here (was 4h — this page's own
					// pre-rebuild default — changed per product decision to
					// match /l24/<asset>'s own 1h default) — see TF_WINDOW
					// below for the per-timeframe visible-window convention
					// this page shares with it.
					let INTERVAL = '1h';
					const klineUrl = (iv, limit) =>
						'/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit + '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// This page has no "Expiry"/"Cumulative" controls at all
					// (removed in the /l24-based rebuild) — the 4 gamma legs
					// are always computed cumulatively across every one of
					// ASSET's own expiries active AS OF AS_OF_ISO. It does
					// have its own "Window" dropdown (1h..72h in 1-hour steps
					// then 4d/5d, 24h default — options rendered server-side
					// from the `window_hours` context list, same as
					// /l24/<asset>), restricting the trailing-hours trade
					// window ending at AS_OF_ISO instead of "now".
					let WINDOW_HOURS = 24;
					const fourLegGammaUrl = () =>
						'/api/four-leg-gamma/' + ASSET + '?expiry=all&hours=' + WINDOW_HOURS
						+ '&as_of=' + encodeURIComponent(AS_OF_ISO);

					let tradeCount = null;

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// The AVG line's color is derived from its dominant leg, not a
					// user setting: a call-side dominant leg (LC/SC) -> light green,
					// a put-side one (LP/SP) -> light red — same light green/red this
					// addon uses for the Thales Forecast candle bodies and the /sli
					// page's own single line. Was a "Chart Appearance" color picker
					// until product decision (2026-08-31) made it dominant-leg-derived.
					const AVG_LINE_COLOR_CALL = '#a5d6a7';
					const AVG_LINE_COLOR_PUT  = '#ef9a9a';
					function avgLineColor(legName) {
						return (legName === 'LC' || legName === 'SC') ? AVG_LINE_COLOR_CALL : AVG_LINE_COLOR_PUT;
					}

					// "Settings" button/dialog — user-pickable colors for this
					// page's own 4 gamma-leg lines, persisted
					// per-browser under a key completely independent of
					// /l24/<asset>'s own 'dankbit_l24_chart_colors' and every
					// other page's own color settings, since Time Machine is
					// its own page with its own settings — unchanged by the
					// /l24-based rebuild. The AVG line is not here — its color is
					// dominant-leg-derived (avgLineColor() above).
					const COLOR_STORAGE_KEY = 'dankbit_tm_chart_colors';
					const DEFAULT_COLORS = { bcg: '#000000', bpg: '#000000', scg: '#fb8c00', spg: '#fb8c00' };
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// Watermark — this page only (not /l24/<asset> or the
					// Delta Chart), via Lightweight Charts v4's own built-in
					// `watermark` chart option (drawn directly onto the
					// chart's own canvas, so it's properly clipped/resized
					// along with everything else — not a hand-rolled DOM
					// overlay). Fixed gray, deliberately NOT theme-reactive
					// (unlike every other themed chart option on this page)
					// — a light/dark-switching black-ish/white-ish color
					// went invisible in practice (white-on-white in Light,
					// black-on-black in Dark, reported directly), so a
					// single mid-gray at moderate alpha is used instead,
					// which reads against both a white and a black
					// background without needing to track DARK_MODE at all.
					const WATERMARK_TEXT = 'Dankbit Time Machine';
					const WATERMARK_COLOR = 'rgba(120,120,120,0.35)';

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						watermark: { visible: true, text: WATERMARK_TEXT, fontSize: 36, color: WATERMARK_COLOR, horzAlign: 'center', vertAlign: 'center' },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
						updateWindowVLine();
					});
					chart.timeScale().subscribeVisibleLogicalRangeChange(() => updateWindowVLine());
					// #tf-bar wraps onto extra rows on a narrow viewport (see its
					// own CSS comment) — #exchange-label/#ruler-info (stacked
					// underneath it) track its actual measured bottom edge via
					// this custom property instead of a hardcoded offset, so a
					// taller (wrapped) toolbar can never overlap them.
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();

					// Light-orange fill between LP/SP (when LP is below SP) and between
					// LC/SC (when LC is above SC) — same addBaselineSeries flat-top +
					// baseValue-bottom fill trick /l24/<asset> uses. No border stroke
					// (topLineColor/bottomLineColor transparent) since this is meant as
					// a plain shaded zone, not another bordered box. Added to the chart
					// BEFORE the candlestick series below, so it renders underneath the
					// candles and the LC/LP/SC/SP reference lines (series added later
					// draw on top) rather than muddying them.
					const putFillSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: 'rgba(0,0,0,0)', topFillColor1: 'rgba(255,152,0,0.22)', topFillColor2: 'rgba(255,152,0,0.22)',
						bottomLineColor: 'rgba(0,0,0,0)', bottomFillColor1: 'rgba(255,152,0,0.22)', bottomFillColor2: 'rgba(255,152,0,0.22)',
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const callFillSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: 'rgba(0,0,0,0)', topFillColor1: 'rgba(255,152,0,0.22)', topFillColor2: 'rgba(255,152,0,0.22)',
						bottomLineColor: 'rgba(0,0,0,0)', bottomFillColor1: 'rgba(255,152,0,0.22)', bottomFillColor2: 'rgba(255,152,0,0.22)',
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis a little past the last historical candle, same
					// mechanism /l24/<asset>'s own futureAxisSeries uses — just
					// breathing room for the 4 gamma price lines' own axis
					// labels, not a claim about real future price action (this
					// page shows a frozen past moment, not a live forecast).
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// resolved As-Of/Window reading — same createPriceLine()
					// pattern /l24/<asset> uses — redrawn fresh whenever As
					// Of/Timeframe/Window changes.
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null, avgGammaPriceLine = null;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					function statusText() {
						// The picker is Berlin wall-clock — show that, plus the
						// UTC instant it resolved to (what actually filters
						// trades) in parentheses, so both are visible at a glance.
						const berlin = document.getElementById('as-of-input').value || '?';
						const utc = AS_OF_ISO ? AS_OF_ISO + 'Z' : '?';
						return ASSET + ' · L24 (Time Machine, all expiries, ' + WINDOW_HOURS + 'h trailing window)'
							+ '  ·  As of ' + berlin + ' Berlin (' + utc + ')' + tradeCountSuffix();
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention /l24/<asset>'s
					// own TF_WINDOW uses.
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					const FUTURE_MARGIN_DAYS = 5;

					// Time span the LP/SP and LC/SC fill rectangles stretch across —
					// from the earliest loaded candle out to the same future-axis
					// edge applyVisibleRange() scrolls to, so the shaded zone spans
					// the full plotted width instead of stopping at the last real bar.
					function fillRectTimeRange() {
						if (!realCandles.length) return null;
						return {
							fromTime: realCandles[0].time,
							toTime: realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400,
						};
					}

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
						updateWindowVLine();
					}

					// Snaps an arbitrary instant to the nearest loaded candle
					// at-or-before it — same binary-search technique
					// /l24/<asset> uses (timeToCoordinate() only resolves a
					// coordinate for a time that exactly matches an existing
					// data/whitespace point on the shared time axis, it does
					// NOT interpolate an isolated point in between — see
					// updateWindowVLine() below).
					function nearestCandleTimeAtOrBefore(t) {
						if (!realCandles.length) return null;
						let lo = 0, hi = realCandles.length - 1, ans = -1;
						while (lo <= hi) {
							const mid = (lo + hi) >> 1;
							if (realCandles[mid].time <= t) { ans = mid; lo = mid + 1; }
							else hi = mid - 1;
						}
						return ans === -1 ? realCandles[0].time : realCandles[ans].time;
					}

					// Formats the selected Window for the line's own text label
					// — "<N>h" up to 72h, "<N>d" for the whole-day entries above
					// it (4d/5d), matching the Window dropdown's own option
					// labels exactly (see _l24_window_options() in main.py),
					// same as /l24/<asset>.
					function formatWindowLabel(hours) {
						return (hours > 72 && hours % 24 === 0) ? (hours / 24) + 'd' : hours + 'h';
					}

					// "Window Line" checkbox (right after "Theme", checked by
					// default) — a plain client-side show/hide flag for the
					// single Window vertical line + label; no effect on the
					// Window dropdown or any fetch. Lets the user hide the line
					// to see the candles under it.
					let VLINE_SHOWN = true;
					function onToggleVLine() {
						VLINE_SHOWN = document.getElementById('vline-toggle').checked;
						updateWindowVLine();
					}

					// Positions the single Window reference line (and its
					// label) at the candle WINDOW_HOURS hours before AS_OF_ISO
					// — the start of the currently selected trailing Window,
					// relative to the inspected moment rather than real "now"
					// (per this page's "testing the past" design; asOfEpochSeconds()
					// instead of Date.now(), the one difference from /l24's own
					// updateWindowVLine()). An As-Of moment is frozen, so unlike
					// /l24 this line never needs to keep creeping forward on a
					// timer once positioned (no setInterval on this page at all
					// — see init()/reloadForAsOf() below). The line and its
					// label are always shown/hidden/positioned together so they
					// can never drift out of sync. Fully hidden when the
					// "Window Line" checkbox is unchecked (VLINE_SHOWN false).
					function updateWindowVLine() {
						const vline = document.getElementById('window-vline');
						const label = document.getElementById('window-vline-label');
						if (!vline) return;
						if (!VLINE_SHOWN) {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
							return;
						}
						const asOfEpoch = asOfEpochSeconds();
						if (asOfEpoch === null) {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
							return;
						}
						const t = asOfEpoch - WINDOW_HOURS * 3600 + tzOffset;
						const snapped = nearestCandleTimeAtOrBefore(t);
						const x = snapped === null ? null : chart.timeScale().timeToCoordinate(snapped);
						if (x === null || x === undefined) {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
							return;
						}
						const rect = chartContainerEl.getBoundingClientRect();
						const left = Math.round(rect.left + x);
						vline.style.left = left + 'px';
						vline.style.display = 'block';
						if (label) {
							label.textContent = formatWindowLabel(WINDOW_HOURS);
							label.style.left = left + 'px';
							label.style.display = 'block';
						}
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
						// rebuildSeriesData() already calls updateWindowVLine() once,
						// but that happens BEFORE applyVisibleRange() establishes
						// the real visible window on first load — recompute here
						// too so the lines reflect the actual window immediately.
						updateWindowVLine();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						setStatus(statusText());
					}

					async function setWindow(hours) {
						WINDOW_HOURS = parseInt(hours, 10);
						updateWindowVLine();
						await refreshFourLegGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values —
					// same convention /l24/<asset>'s own formatAbbreviated() uses.
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Fetches and redraws the 4 gamma-leg lines (+ AVG) for the
					// current WINDOW_HOURS as of AS_OF_ISO — same shape as
					// /l24/<asset>'s own refreshFourLegGamma() (SC/SP labels
					// with no combined magnitude suffix, AVG label
					// "<dom leg> $<dom leg price> | <avg gamma value>",
					// light-orange LP/SP+LC/SC fill),
					// minus the periodic re-poll (this only ever runs in
					// direct response to a control change or the "Refresh
					// Lines" button on this page).
					async function refreshFourLegGamma() {
						showSpinner();
						try {
							const data = await (await fetch(fourLegGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							// 0 (not null) once resolved with no trades at all in
							// the current window — null only ever means "haven't
							// fetched yet", so tradeCountSuffix() can tell "0
							// trades" apart from "not loaded".
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (avgGammaPriceLine) { series.removePriceLine(avgGammaPriceLine); avgGammaPriceLine = null; }
							if (!latest) {
								putFillSeries.setData([]);
								callFillSeries.setData([]);
								return;
							}

							// 0.0 means absent (same convention every gamma_band/
							// smart_liq_*_price field in this addon uses) — no
							// line drawn rather than a spurious price-0 line.
							if (latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: chartColors.bcg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bcg,
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: chartColors.bpg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bpg,
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							if (latest.scg_price) {
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: chartColors.scg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.scg,
									title: 'SC ' + formatAbbreviated(latest.scg_value),
								});
							}
							if (latest.spg_price) {
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: chartColors.spg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.spg,
									title: 'SP ' + formatAbbreviated(latest.spg_value),
								});
							}
							// Average of the legs' own gamma PRICE levels (not their
							// gamma value) — over whichever legs are actually present
							// (0.0 means absent, same convention as the 4 lines
							// above), not a fixed /4. The label additionally shows
							// the dominant leg (largest |gamma value| among present
							// legs) + its own $-prefixed price, then the average of
							// those legs' gamma VALUES: "<dom leg> $<dom leg price> |
							// <avg gamma value>", e.g. "LC $81,200 | 71M" — same as
							// /l24/<asset> (positions swapped + $ added per product
							// decision 2026-08-31, matching /sli).
							const gammaLegs = [
								{ name: 'LC', price: latest.bcg_price, value: latest.bcg_value },
								{ name: 'LP', price: latest.bpg_price, value: latest.bpg_value },
								{ name: 'SC', price: latest.scg_price, value: latest.scg_value },
								{ name: 'SP', price: latest.spg_price, value: latest.spg_value },
							].filter(leg => leg.price);
							if (gammaLegs.length) {
								const avgGammaPrice = gammaLegs.reduce((a, leg) => a + leg.price, 0) / gammaLegs.length;
								const avgGammaValue = gammaLegs.reduce((a, leg) => a + leg.value, 0) / gammaLegs.length;
								const dominantLeg = gammaLegs.reduce((a, b) => Math.abs(b.value) > Math.abs(a.value) ? b : a);
								const avgColor = avgLineColor(dominantLeg.name);
								avgGammaPriceLine = series.createPriceLine({
									price: avgGammaPrice, color: avgColor, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Dashed,
									axisLabelVisible: true, axisLabelColor: avgColor,
									title: dominantLeg.name + ' $' + Math.round(dominantLeg.price).toLocaleString('en-US') + ' | ' + formatAbbreviated(avgGammaValue),
								});
							}

							// Light-orange shaded zone between LP/SP when LP sits below SP,
							// and between LC/SC when LC sits above SC — see putFillSeries/
							// callFillSeries above. 0.0 (falsy) on either price means that
							// leg had no trades in the window, same absent-price convention
							// the lines above already check, so the fill is skipped rather
							// than drawn against a spurious price-0 edge.
							const fillRange = fillRectTimeRange();
							if (fillRange && latest.bpg_price && latest.spg_price && latest.bpg_price < latest.spg_price) {
								putFillSeries.applyOptions({ baseValue: { type: 'price', price: latest.bpg_price } });
								putFillSeries.setData([
									{ time: fillRange.fromTime, value: latest.spg_price },
									{ time: fillRange.toTime, value: latest.spg_price },
								]);
							} else {
								putFillSeries.setData([]);
							}
							if (fillRange && latest.bcg_price && latest.scg_price && latest.bcg_price > latest.scg_price) {
								callFillSeries.applyOptions({ baseValue: { type: 'price', price: latest.scg_price } });
								callFillSeries.setData([
									{ time: fillRange.fromTime, value: latest.bcg_price },
									{ time: fillRange.toTime, value: latest.bcg_price },
								]);
							} else {
								callFillSeries.setData([]);
							}
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshFourLegGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshFourLegGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					// Re-runs every fetch on this page against the current
					// AS_OF_ISO — called whenever the "As Of" input changes or
					// the "Now" button is pressed. Candles/gamma legs both
					// depend on AS_OF_ISO, so both are re-fetched together
					// (unlike setTf/setWindow, which each only touch the one
					// thing they control). No Expiry list to reload anymore
					// (removed in the /l24-based rebuild) — the 4 gamma legs
					// are always cumulative across every expiry active as of
					// AS_OF_ISO.
					async function reloadForAsOf() {
						showSpinner();
						try {
							await loadCandles();
							await refreshFourLegGamma();
							setStatus(statusText());
						} catch (e) {
							setStatus('Error: ' + e.message);
						} finally {
							hideSpinner();
						}
					}

					function onAsOfChange() {
						const value = document.getElementById('as-of-input').value;
						if (!value) return;
						setAsOfInput(value);
						reloadForAsOf();
					}

					// Jumps the picker to the current Berlin date and hour
					// (minutes zeroed, via toDatetimeLocalBerlin()).
					function jumpToNow() {
						setAsOfInput(toDatetimeLocalBerlin(new Date()));
						reloadForAsOf();
					}

					async function init() {
						try {
							setAsOfInput(INITIAL_AS_OF || defaultAsOfBerlinNaive());
							await loadCandles();
							await refreshFourLegGamma();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					// No setInterval calls at all on this page — an As-Of
					// moment is frozen by definition, so unlike /l24/<asset>
					// (candle poll, gamma-leg poll, and a 5s vline-advance
					// tick) there's nothing here that needs to keep moving
					// forward in real time once AS_OF_ISO stops changing.
				//
